(7662115, 1248376, 96815, '<td valign="top">Nice capture. It''s a bit light for a ''crowd'' in my opinion, but these days that will do!</td>', 'Nice capture. It''s a bit light for a ''crowd'' in my opinion, but these days that will do!', '2020-05-10 12:04:49.000000', NULL, 1),
(7662116, 1248883, 96815, '<td valign="top">This is a bit too over-exposed for my taste. This is one of those images where I wish the crowd wasn''t there... even though that is the point of the challenge!</td>', 'This is a bit too over-exposed for my taste. This is one of those images where I wish the crowd wasn''t there... even though that is the point of the challenge!', '2020-05-10 12:07:25.000000', NULL, 1),
